contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address other) public payable {
        require(other != address(this));

        uint balOtherBefore = c.getBalance(other); if (__ESBMC_reverted()) return;
        uint balSelfBefore = c.getBalance(address(this)); if (__ESBMC_reverted()) return;

        c.withdrawBalance(); if (__ESBMC_reverted()) return;

        uint balOtherAfter = c.getBalance(other); if (__ESBMC_reverted()) return;
        uint balSelfAfter = c.getBalance(address(this)); if (__ESBMC_reverted()) return;

        assert(balSelfAfter == 0 && balOtherAfter == balOtherBefore);
    }

    receive() external payable {}
}

